cat > app/page.tsx <<'EOF'
import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/catalog'

const priceFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

export default async function Page() {
  async function syncCatalog() {
    'use server'

    revalidateTag('products', 'max')
  }

  const products = await getProducts()

  return (
    <main className=\"catalog\">
      <header className=\"catalog-header\">
        <div>
          <p className=\"eyebrow\">Store administration</p>
          <h1>Product catalog</h1>
          <p className=\"description\">
            Browse your products and keep catalog data in sync.
          </p>
        </div>
        <form action={syncCatalog}>
          <button type=\"submit\">Sync latest catalog</button>
        </form>
      </header>

      <p className=\"sync-note\">
        Sync marks the catalog for refresh. The current list may be briefly
        out of date while fresh data loads in the background on the next visit.
      </p>

      <section className=\"product-section\" aria-labelledby=\"products-heading\">
        <div className=\"section-header\">
          <div>
            <h2 id=\"products-heading\">Products</h2>
            <p>{products.length} {products.length === 1 ? 'product' : 'products'}</p>
          </div>
        </div>
        <div className=\"table-container\">
          <table>
            <thead>
              <tr>
                <th scope=\"col\">Product</th>
                <th scope=\"col\">Product ID</th>
                <th scope=\"col\" className=\"price\">Price</th>
              </tr>
            </thead>
            <tbody>
              {products.map((product) => (
                <tr key={product.id}>
                  <td className=\"product-name\">{product.name}</td>
                  <td className=\"product-id\">{product.id}</td>
                  <td className=\"price\">{priceFormatter.format(product.price)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {products.length === 0 && <p className=\"empty-state\">No products found.</p>}
      </section>
    </main>
  )
}
EOF
