  font-family: Arial, Helvetica, sans-serif;
  color: #17212b;
  background: #f5f7f8;
}

* { box-sizing: border-box; }
body { margin: 0; }

.catalog {
  max-width: 1080px;
  margin: 0 auto;
  padding: 64px 24px;
}

.catalog-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
}

.eyebrow {
  margin: 0 0 12px;
  color: #537069;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 8px; font-size: 32px; letter-spacing: -.03em; }
.description { margin-bottom: 0; color: #617078; line-height: 1.5; }

button {
  border: 0;
  border-radius: 6px;
  padding: 12px 18px;
  background: #174e40;
  color: white;
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
button:hover { background: #103d32; }
button:focus-visible { outline: 3px solid #87b8a8; outline-offset: 3px; }

.sync-note {
  margin: 28px 0;
  padding: 14px 16px;
  border: 1px solid #d9e6e1;
  border-radius: 6px;
  background: #edf5f1;
  color: #416156;
  font-size: 14px;
  line-height: 1.5;
}

.product-section {
  overflow: hidden;
  border: 1px solid #dfe5e5;
  border-radius: 8px;
  background: white;
}
.section-header { padding: 22px 24px; }
.section-header h2 { margin-bottom: 5px; font-size: 18px; }
.section-header p { margin-bottom: 0; color: #718087; font-size: 13px; }
.table-container { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; text-align: left; }
th, td { padding: 16px 24px; border-top: 1px solid #edf0f0; font-size: 14px; }
th { background: #fafbfb; color: #718087; font-size: 12px; font-weight: 600; }
td { color: #34464b; }
.product-name { color: #17212b; font-weight: 600; }
.product-id { color: #718087; }
.price { text-align: right; font-variant-numeric: tabular-nums; }
.empty-state { margin: 0; padding: 24px; color: #718087; }

@media (max-width: 600px) {
  .catalog { padding: 36px 16px; }
  .catalog-header { align-items: flex-start; flex-direction: column; }
  h1 { font-size: 28px; }
  th, td { padding: 14px 16px; }
}
